#!/usr/bin/env bash
# Shared helpers. Source this file; do not execute it.

# Languages generated by protogen. Each has a template buf.gen.<lang>.yaml.
ALL_LANGS="go java scala rust"

GO_BASE_MODULE="${GO_BASE_MODULE:-github.com/huponx/protogen/go}"

# go_layout <ref>
# Sets GO_MAJOR, GO_DIR, GO_MODULE and GO_TAG_PREFIX from a semver ref (v1.2.3).
#   major 0/1: go/    module <base>      tag go/vX.Y.Z
#   major >=2: go/vN/ module <base>/vN   tag go/vN/vN.Y.Z
# The Go tag for a ref is "${GO_TAG_PREFIX}/${ref}".
go_layout() {
  local ref="${1:-}"
  if ! [[ "${ref}" =~ ^v([0-9]+)\.[0-9]+\.[0-9]+$ ]]; then
    echo "go_layout: '${ref}' is not a semver tag (vX.Y.Z)" >&2
    return 1
  fi
  GO_MAJOR="${BASH_REMATCH[1]}"
  if [ "${GO_MAJOR}" -ge 2 ]; then
    GO_DIR="go/v${GO_MAJOR}"
    GO_MODULE="${GO_BASE_MODULE}/v${GO_MAJOR}"
    GO_TAG_PREFIX="go/v${GO_MAJOR}"
  else
    GO_DIR="go"
    GO_MODULE="${GO_BASE_MODULE}"
    GO_TAG_PREFIX="go"
  fi
}

# stub_dir <lang>: directory (relative to protogen root) holding generated files.
stub_dir() {
  case "$1" in
    go) echo "${GO_DIR:-go}" ;;
    java) echo "java/src/main/java" ;;
    scala) echo "scala/src/main/scala" ;;
    rust) echo "rust/src/gen" ;;
    *) echo "unknown language: $1" >&2; return 1 ;;
  esac
}

# lang_root <lang>: directory with the build file of that language.
lang_root() {
  case "$1" in
    go) echo "${GO_DIR:-go}" ;;
    java|scala|rust) echo "$1" ;;
    *) echo "unknown language: $1" >&2; return 1 ;;
  esac
}

# render_template <proto_dir> <lang> <dest>
# Writes buf.gen.<lang>.yaml with ${GO_MODULE} and ${GO_DIR} substituted.
render_template() {
  local proto_dir="$1" lang="$2" dest="$3" src
  src="${proto_dir}/buf.gen.${lang}.yaml"
  if [ ! -f "${src}" ]; then
    echo "missing template ${src}" >&2
    return 1
  fi
  sed -e "s|\${GO_MODULE}|${GO_MODULE:-}|g" -e "s|\${GO_DIR}|${GO_DIR:-go}|g" "${src}" > "${dest}"
}

# clean_stubs <out_dir> <lang>
# Removes previously generated files of one language (never build files).
# buf generate does not delete stubs of removed .proto files.
clean_stubs() {
  local out_dir="$1" lang="$2" dir f rel
  dir="${out_dir}/$(stub_dir "${lang}")"
  [ -d "${dir}" ] || return 0
  case "${lang}" in
    go)
      # go/ also contains go/vN/ modules of later majors: leave those alone.
      while IFS= read -r f; do
        rel="${f#"${dir}"/}"
        case "${rel}" in
          v[0-9]*/*) continue ;;
        esac
        rm -f "${f}"
      done < <(find "${dir}" -name '*.pb.go')
      find "${dir}" -mindepth 1 -type d -empty -delete
      ;;
    *)
      rm -rf "${dir}"
      ;;
  esac
}

# list_stub_files <out_dir> <lang>
# Prints files (relative to out_dir) that publishing must carry for one language:
# the generated stubs, plus go.mod/go.sum for Go (tidy updates them).
list_stub_files() {
  local out_dir="$1" lang="$2" dir f rel
  dir="$(stub_dir "${lang}")"
  [ -d "${out_dir}/${dir}" ] || return 0
  case "${lang}" in
    go)
      while IFS= read -r f; do
        rel="${f#"${out_dir}/${dir}"/}"
        case "${rel}" in
          v[0-9]*/*) continue ;;
        esac
        echo "${f#"${out_dir}"/}"
      done < <(find "${out_dir}/${dir}" -type f \( -name '*.pb.go' -o -name go.mod -o -name go.sum \))
      ;;
    *)
      ( cd "${out_dir}" && find "${dir}" -type f )
      ;;
  esac
}
